 void shell(String title){sequence++;canvas=null;root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(PaperActivity.PAPER);TextView heading=text(title,22);root.addView(heading);setContentView(root);}
 void button(LinearLayout parent,String title,Runnable action){TextView view=text(title,16);view.setMinHeight(dp(48));view.setGravity(Gravity.CENTER_VERTICAL);view.setBackgroundResource(R.drawable.sky_control);parent.addView(view,new LinearLayout.LayoutParams(-1,-2));view.setFocusable(true);view.setOnClickListener(value->action.run());}
 byte[] read(File file,int max)throws Exception{return BookData.read(new FileInputStream(file),max);}JSONObject meta(File file)throws Exception{return new JSONObject(new String(read(file,150000),"UTF-8"));}
 void library(){if(!saveCurrent())return;if(renderTask!=null)renderTask.cancel(true);shell("Imported colouring books");button(root,"Import PDF / EPUB / CBZ / image",this::pick);button(root,"Done",this::finish);ScrollView scroll=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));list.addView(text("Freehand colouring saved per page; originals are unchanged. Import trusted files only: the bundled legacy PDF engine is old. EPUB support uses embedded raster images, not text layout or DRM.",15));File[] files=directory().listFiles();int count=0;if(files!=null)for(File entry:files)if(entry.isDirectory())try{JSONObject value=meta(new File(entry,"meta.json"));button(list,value.optString("title")+" / "+value.optInt("count")+" pages",()->open(entry,value,0));View row=list.getChildAt(list.getChildCount()-1);row.setOnLongClickListener(view->{new AlertDialog.Builder(this).setMessage("Delete this imported copy and its saved colouring? Your original file is unchanged.").setPositiveButton("Delete",(dialog,which)->{erase(entry);library();}).setNegativeButton("Cancel",null).show();return true;});count++;}catch(Exception ignored){}if(count==0)list.addView(text("No imported colouring books yet.",18));}
 void pick(){if(!saveCurrent())return;Intent intent=new Intent(Build.VERSION.SDK_INT>=19?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_GET_CONTENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);if(Build.VERSION.SDK_INT>=19)intent.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","application/epub+zip","application/zip","application/x-cbz","application/vnd.comicbook+zip","image/*"});try{startActivityForResult(Intent.createChooser(intent,"Import colouring book"),931);}catch(Exception error){Toast.makeText(this,"File picker unavailable",1).show();}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=931||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();String label="Colouring book";try(Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())label=cursor.getString(0);}catch(Exception ignored){}final String name=label==null?"Colouring book":label.substring(0,Math.min(120,label.length()));shell("Importing colouring book");root.addView(text("Validating "+name+"...",18));button(root,"Library",this::library);final int ticket=sequence;io.submit(()->{File target=new File(directory(),UUID.randomUUID().toString());try{File[] all=directory().listFiles();if(all!=null&&all.length>=40)throw new IOException("Colouring library limit reached");long used=used(directory());if(!target.mkdirs())throw new IOException("Cannot create import folder");File source=new File(target,"source.bin");long size=0;try(InputStream input=getContentResolver().openInputStream(uri);OutputStream output=new FileOutputStream(source)){if(input==null)throw new IOException("Cannot read file");byte[] buffer=new byte[16384];int n;while((n=input.read(buffer))!=-1){size+=n;if(size>52428800L||used+size>209715200L)throw new IOException("Import exceeds 50MiB file / 200MiB library limit");output.write(buffer,0,n);}}byte[] magic=new byte[5];try(InputStream input=new FileInputStream(source)){input.read(magic);}String format;JSONArray images=new JSONArray();int count;if(magic[0]=='%'&&magic[1]=='P'&&magic[2]=='D'&&magic[3]=='F'&&magic[4]=='-'){format="PDF";PdfPages.Page first=PdfPages.render(this,source,0,80,100);count=first.count;first.image.recycle();}else if(magic[0]=='P'&&magic[1]=='K'){try(ZipFile zip=new ZipFile(source)){validate(zip);if(zip.getEntry("mimetype")!=null&&new String(BookData.entry(zip,"mimetype",100),"UTF-8").trim().equals("application/epub+zip")){format="EPUB";for(String path:epub(zip))images.put(path);}else{format="CBZ";ArrayList<String> names=new ArrayList<>();Enumeration<? extends ZipEntry> entries=zip.entries();while(entries.hasMoreElements()){ZipEntry entry=entries.nextElement();if(!entry.isDirectory()&&raster(entry.getName()))names.add(entry.getName());}Collections.sort(names);for(String path:names)images.put(path);}count=images.length();}}else{format="IMAGE";BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(source.getPath(),bounds);if(bounds.outWidth<1||bounds.outHeight<1)throw new IOException("Choose PDF, image EPUB, CBZ, PNG, JPEG, GIF or WebP");count=1;}if(count<1||count>300)throw new IOException("Book must contain 1-300 supported pages");JSONObject value=new JSONObject().put("title",name).put("format",format).put("count",count).put("images",images);ArtFiles.write(new AtomicFile(new File(target,"meta.json")),value.toString().getBytes("UTF-8"));main.post(()->{if(!closed&&ticket==sequence)open(target,value,0);});}catch(Exception error){erase(target);main.post(()->{if(!closed){Toast.makeText(this,"Import failed / "+error.getMessage(),1).show();if(ticket==sequence)library();}});}});}
 static long used(File file){if(!file.isDirectory())return file.length();long size=0;File[] files=file.listFiles();if(files!=null)for(File child:files)size+=used(child);return size;}static void erase(File file){File[] files=file.listFiles();if(files!=null)for(File child:files)erase(child);file.delete();}
 static boolean raster(String path){String value=path.toLowerCase(Locale.US);return value.endsWith(".png")||value.endsWith(".jpg")||value.endsWith(".jpeg")||value.endsWith(".webp")||value.endsWith(".gif");}
 static void validate(ZipFile zip)throws Exception{int count=0;long size=0;Enumeration<? extends ZipEntry> entries=zip.entries();while(entries.hasMoreElements()){ZipEntry entry=entries.nextElement();size+=Math.max(0,entry.getSize());if(++count>3000||size>104857600L)throw new IOException("Archive exceeds limits");}if(zip.getEntry("META-INF/encryption.xml")!=null)throw new IOException("Encrypted EPUB is unsupported");}
 static XmlPullParser xml(byte[] bytes)throws Exception{String value=new String(bytes,"UTF-8");if(value.toUpperCase(Locale.US).contains("<!DOCTYPE"))throw new IOException("DOCTYPE is unsupported");return BookData.parser(bytes);}
 static ArrayList<String> epub(ZipFile zip)throws Exception{XmlPullParser parser=xml(BookData.entry(zip,"META-INF/container.xml",1000000));String opf=null;for(int event=parser.getEventType();event!=XmlPullParser.END_DOCUMENT;event=parser.next())if(event==XmlPullParser.START_TAG&&parser.getName().equals("rootfile")){opf=parser.getAttributeValue(null,"full-path");break;}if(opf==null)throw new IOException("Missing EPUB package");opf=BookData.path("",opf);parser=xml(BookData.entry(zip,opf,2000000));LinkedHashMap<String,String> manifest=new LinkedHashMap<>();LinkedHashSet<String> pictures=new LinkedHashSet<>();ArrayList<String> spine=new ArrayList<>();for(int event=parser.getEventType();event!=XmlPullParser.END_DOCUMENT;event=parser.next())if(event==XmlPullParser.START_TAG){if(parser.getName().equals("item")){String id=parser.getAttributeValue(null,"id"),href=parser.getAttributeValue(null,"href");if(id!=null&&href!=null){String path=BookData.path(opf,href);manifest.put(id,path);if(raster(path))pictures.add(path);}}else if(parser.getName().equals("itemref"))spine.add(parser.getAttributeValue(null,"idref"));}LinkedHashSet<String> ordered=new LinkedHashSet<>();for(String id:spine){String path=manifest.get(id);if(path==null)continue;if(pictures.contains(path)){ordered.add(path);continue;}if(!(path.endsWith(".xhtml")||path.endsWith(".html")||path.endsWith(".htm")))continue;XmlPullParser chapter=xml(BookData.entry(zip,path,2000000));for(int event=chapter.getEventType();event!=XmlPullParser.END_DOCUMENT;event=chapter.next())if(event==XmlPullParser.START_TAG&&(chapter.getName().equals("img")||chapter.getName().equals("image"))){String src=chapter.getAttributeValue(null,"src");if(src==null)src=chapter.getAttributeValue(null,"href");if(src==null)src=chapter.getAttributeValue("http://www.w3.org/1999/xlink","href");if(src!=null){String image=BookData.path(path,src);if(pictures.contains(image))ordered.add(image);}}}if(ordered.isEmpty())ordered.addAll(pictures);if(ordered.size()>300)throw new IOException("Too many image pages");return new ArrayList<>(ordered);}
 Bitmap decode(byte[] bytes)throws Exception{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth<1||bounds.outHeight<1||(long)bounds.outWidth*bounds.outHeight>40000000L)throw new IOException("Unsupported or oversized image");bounds.inSampleSize=1;while(bounds.outWidth/bounds.inSampleSize>1000||bounds.outHeight/bounds.inSampleSize>1400)bounds.inSampleSize*=2;bounds.inJustDecodeBounds=false;Bitmap value=BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(value==null)throw new IOException("Cannot decode page image");return value;}
 void open(File selected,JSONObject metadata,int index){if(!saveCurrent())return;if(renderTask!=null)renderTask.cancel(true);folder=selected;book=metadata;page=Math.max(0,Math.min(metadata.optInt("count")-1,index));shell(metadata.optString("title"));HorizontalScrollView scroll=new HorizontalScrollView(this);LinearLayout controls=new LinearLayout(this);scroll.addView(controls);root.addView(scroll);String[] names={"Library","Previous","Next","Undo","Clear colours","Save"};for(int i=0;i<names.length;i++){final int action=i;TextView control=text(names[i],16);control.setMinHeight(dp(48));controls.addView(control);control.setFocusable(true);control.setOnClickListener(view->{if(action==0)library();else if(action==1)open(folder,book,page-1);else if(action==2)open(folder,book,page+1);else if(canvas!=null){if(action==3){canvas.model.undo();canvas.dirty=true;canvas.invalidate();saveCurrent();}else if(action==4)new AlertDialog.Builder(this).setMessage("Clear colours from this page?").setPositiveButton("Clear",(dialog,which)->{canvas.model.clear();canvas.dirty=true;canvas.invalidate();saveCurrent();}).setNegativeButton("Cancel",null).show();else saveCurrent();}});}LinearLayout palette=new LinearLayout(this);root.addView(palette);for(int color:new int[]{0x88ed6a80,0x88ffb44f,0x88ffdf70,0x8865caa3,0x885a9dea,0x88a881df,0x88555555}){View swatch=new View(this);swatch.setBackgroundColor(color|0xff000000);swatch.setContentDescription("Colour "+Integer.toHexString(color));palette.addView(swatch,new LinearLayout.LayoutParams(0,dp(40),1));swatch.setOnClickListener(view->ink=color);}status=text("Loading page "+(page+1)+" / "+book.optInt("count"),15);root.addView(status);FrameLayout stage=new FrameLayout(this);root.addView(stage,new LinearLayout.LayoutParams(-1,0,1));final int ticket=sequence,number=page;renderTask=io.submit(()->{try{File source=new File(selected,"source.bin");String format=metadata.getString("format");Bitmap image;if(format.equals("PDF"))image=PdfPages.render(this,source,number,1000,1400).image;else if(format.equals("IMAGE"))image=decode(read(source,52428800));else try(ZipFile zip=new ZipFile(source)){image=decode(BookData.entry(zip,metadata.getJSONArray("images").getString(number),8388608));}File saved=new File(selected,"paint-"+number+".json");StudyInk.Model model=saved.exists()?StudyInk.Model.parse(new String(read(saved,300000),"UTF-8")):new StudyInk.Model();main.post(()->{if(closed||ticket!=sequence){image.recycle();return;}canvas=new PageCanvas(image,model);stage.addView(canvas,new FrameLayout.LayoutParams(-1,-1));status.setText("Page "+(number+1)+" / "+metadata.optInt("count")+" / freehand colour, saved locally");});}catch(Exception error){main.post(()->{if(!closed&&ticket==sequence)status.setText("Cannot open page safely / "+error.getMessage());});}catch(OutOfMemoryError error){main.post(()->{if(!closed&&ticket==sequence)status.setText("Not enough memory for this page");});}});}
 boolean saveCurrent(){if(canvas==null||!canvas.dirty)return true;try{canvas.model.end();byte[] bytes=canvas.model.json().getBytes("UTF-8");if(bytes.length>300000||used(directory())+bytes.length>209715200L)throw new IOException("Colouring storage limit reached");ArtFiles.write(new AtomicFile(new File(folder,"paint-"+page+".json")),bytes);canvas.dirty=false;status.setText("Page "+(page+1)+" / saved on this device");return true;}catch(Exception error){status.setText("NOT SAVED / keep page open and check storage");return false;}}
 class PageCanvas extends View{final Bitmap image;final StudyInk.Model model;final Paint paint=new Paint(3);boolean dirty=false;PageCanvas(Bitmap value,StudyInk.Model saved){super(ColouringBookActivity.this);image=value;model=saved;setContentDescription("Freehand colouring page. Undo removes the last colour stroke; original page unchanged.");}RectF box(){float scale=Math.min(getWidth()/(float)image.getWidth(),getHeight()/(float)image.getHeight());float w=image.getWidth()*scale,h=image.getHeight()*scale;return new RectF((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);}protected void onDraw(Canvas target){target.drawColor(0xffe8e2d5);RectF bounds=box();target.drawBitmap(image,null,bounds,paint);model.draw(target,bounds);}public boolean onTouchEvent(MotionEvent event){RectF bounds=box();if(bounds.width()<=0||bounds.height()<=0)return false;int action=event.getActionMasked();if(event.getPointerCount()>1||action==MotionEvent.ACTION_CANCEL){model.cancel();invalidate();return true;}if(action==MotionEvent.ACTION_DOWN){if(!bounds.contains(event.getX(),event.getY()))return false;if(!model.begin((event.getX()-bounds.left)/bounds.width(),(event.getY()-bounds.top)/bounds.height(),ink,22))Toast.makeText(ColouringBookActivity.this,"Page ink limit / undo or clear colours",1).show();dirty=true;}else if(action==MotionEvent.ACTION_MOVE)model.add((event.getX()-bounds.left)/bounds.width(),(event.getY()-bounds.top)/bounds.height());else if(action==MotionEvent.ACTION_UP){model.end();saveCurrent();performClick();}invalidate();return true;}public boolean performClick(){super.performClick();return true;}}
 public void onBackPressed(){if(canvas!=null)library();else super.onBackPressed();}protected void onPause(){saveCurrent();super.onPause();}protected void onDestroy(){closed=true;sequence++;if(renderTask!=null)renderTask.cancel(true);io.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
